using System.Collections.ObjectModel;
using System.Xml.Serialization;
using WPFUI.Factories;
namespace WPFUI.Models;

public class Monster : LivingEntity
{   
    private readonly List<ItemPercentage> _lootTable = new List<ItemPercentage>();
    public int ID {get;}
    public string ImageName { get;}
    public int RewardedExperiencePoints { get; }

    public Monster(int id,string name, string imageName, int maximumHitPoints, GameItem currentWeapon,int rewardedExperiencePoints, int rewardedGold) :
    base(name, maximumHitPoints, maximumHitPoints, rewardedGold)
    {   
        ID = id;
        ImageName = imageName;
        CurrentWeapon = currentWeapon;
        RewardedExperiencePoints = rewardedExperiencePoints;
    }

    public void AddItemToLootTable(int id, int percentage)
    {
        _lootTable.RemoveAll(ip => ip.ID == id);
        _lootTable.Add(new ItemPercentage(id, percentage));
    }

    public Monster GetNewInstance()
    {
        Monster newMonster = new Monster(ID, Name, ImageName, MaximumHitPoints, CurrentWeapon, RewardedExperiencePoints, Gold);
        foreach(ItemPercentage itemPercentage in _lootTable){
            newMonster.AddItemToLootTable(itemPercentage.ID, itemPercentage.Percentage);
            if(RandomNumberGenerator.NumberBetween(1, 100) <= itemPercentage.Percentage)
            {
                newMonster.AddItemToInventory(ItemFactory.CreateGameItem(itemPercentage.ID));
            }
        }
        return newMonster;
    }
}

